// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;

import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address originalOwner, address caller) public {
        vm.assume(originalOwner != address(0));
        vm.assume(caller != originalOwner);

        vm.prank(c.owner());
        c.transferOwnership(originalOwner);

        vm.prank(caller);
        address returned = c.owner();

        assertTrue(returned == originalOwner);
    }
}
